class LRU:
    def __init__(self, n):
        self.n = n; self.d = OrderedDict()
    def get(self, k):
        if k not in self.d: return -1
        self.d.move_to_end(k); return self.d[k]
    def put(self, k, v):
        self.d[k] = v; self.d.move_to_end(k)
        if len(self.d) > self.n: self.d.popitem(last=False)

class Pool:
    def __init__(self): self.free = []; self.used = 0
    def acquire(self):
        if self.free:
            c = self.free.pop()
        else:
            c = connect(); self.used += 1
        return c
    def release(self, c):
        self.free.append(c)

